<?php

namespace App\Services\Signatories\Documents;

use App\Models\Checkin;

/**
 * Goods Received Note (GRN) generated from an approved check-in.
 *
 * Real records on the check-in: user_id + created_at (who prepared it), approved_by + approved_at (+ approved_by_role) and
 * grn_generated_by + grn_generated_at. A check-in that was completed before approvals existed has no person for the last two:
 * it was approved and its GRN generated by "WIMS System", which is shown as a name (no signature image is invented for the system).
 *
 * States: "final" once the GRN exists (the note is issued), otherwise "in_progress" (it is not printable before approval anyway).
 */
final class GoodsReceivedNoteDocument implements SignableDocument
{
    public static function key(): string
    {
        return 'grn';
    }

    public static function label(): string
    {
        return 'Goods Received Note (GRN)';
    }

    public static function actions(): array
    {
        return [
            'prepared' => 'Prepared (the person who entered the check-in)',
            'approved' => 'Approved (the check-in)',
            'generated' => 'Generated (the GRN)',
        ];
    }

    public function find(int $id): ?object
    {
        return Checkin::query()->withoutGlobalScope('mine')->find($id);
    }

    public function state(object $record): string
    {
        return $record->grn_number ? 'final' : 'in_progress';
    }

    public function history(object $record): array
    {
        $h = [];
        if ($record->user_id || $record->created_at) {
            $h['prepared'] = [
                'user_id' => $record->user_id ? (int) $record->user_id : null, 'at' => StockSigningGuard::at($record->created_at), 'name' => null,
                'quality' => $record->user_id && $record->created_at ? 'good' : 'partial', 'note' => null,
            ];
        }
        if (! $record->draft && $record->approved_at) {
            $system = ! $record->approved_by;
            $h['approved'] = [
                'user_id' => $record->approved_by ? (int) $record->approved_by : null, 'at' => StockSigningGuard::at($record->approved_at), 'name' => $system ? 'WIMS Admin' : null,
                'quality' => $system ? 'partial' : 'good',
                'note' => $system ? 'Approved by WIMS System: the check-in was completed before approvals were introduced.' : null,
            ];
        }
        if ($record->grn_number && $record->grn_generated_at) {
            $system = ! $record->grn_generated_by;
            $h['generated'] = [
                'user_id' => $record->grn_generated_by ? (int) $record->grn_generated_by : null, 'at' => StockSigningGuard::at($record->grn_generated_at), 'name' => $system ? 'WIMS Admin' : null,
                'quality' => $system ? 'partial' : 'good',
                'note' => $system ? 'Generated by WIMS System.' : null,
            ];
        }

        return $h;
    }

    public static function defaultMappings(): array
    {
        return [
            ['role' => 'prepared_by', 'action' => 'prepared', 'slot' => 1, 'required' => false, 'show_when' => 'always'],
            ['role' => 'approved_by', 'action' => 'approved', 'slot' => 2, 'required' => false, 'show_when' => 'always'],
            ['role' => 'generated_by', 'action' => 'generated', 'slot' => 3, 'required' => false, 'show_when' => 'always'],
        ];
    }

    public function reference(object $record): string
    {
        return (string) ($record->grn_number ?: ($record->reference ?? ('#' . $record->id)));
    }
}
